"""stream_wire — 把 realtime 部分文本接进 A 路早火

  AgentStream(websockets, /v1/realtime) → on_text(delta) → 累积 → agent._a_try_preempt(text)
  → partial_preempt → route_prefix(多子串) → live 命中 → dispatch 提前执行
失败(连不上/403/无 websockets)时静默降级, 不影响原 A/B 路。
"""
from __future__ import annotations


class StreamWire:
    def __init__(self, agent, url, model="qwen3-asr", commit_ms=300, log=None):
        self.agent = agent
        self.text = ""
        self.n_delta = 0
        self._log = log or (lambda m: None)
        from agent_stream import AgentStream, pcm16  # 同目录
        self._pcm16 = pcm16
        self.s = AgentStream(url, model=model, commit_ms=max(100, int(commit_ms)),
                             on_text=self._on_text, on_log=self._log)

    def start(self):
        self.s.start()

    def stop(self):
        try:
            self.s.stop()
        except Exception:
            pass

    def push(self, blk):
        try:
            if self.s.state == "ready":
                self.s.push(self._pcm16(blk))
        except Exception:
            pass

    def boundary(self):
        """一段(VAD 段)结束: 清空累积文本, 下一段重新开始"""
        self.text = ""
        self.n_delta = 0

    def _on_text(self, delta, final):
        if not delta:
            return
        self.text += delta
        self.n_delta += 1
        if len(self.text) < 3:
            return
        try:
            self.agent._a_try_preempt(self.text)
        except Exception as e:
            self._log(f"   [OPENCODE] 部分文本早火异常（忽略）: {type(e).__name__}: {e}")
